    """Sort events by latency_ms in ascending order."""
    return sorted(events, key=lambda x: x.get('latency_ms', 0))


def sort_by_shard(events: list[dict]) -> list[dict]:
    """Sort events by shard ID in ascending order."""
    return sorted(events, key=lambda x: x.get('shard', 0))


def sort_by_hash(events: list[dict]) -> list[dict]:
    """Sort events by hash string in lexicographical order."""
