def sort_by_id(events: list[dict]) -> list[dict]:
    """Sort events by event ID in ascending order."""
    return sorted(events, key=lambda x: x.get('id', 0))


def filter_by_shard(events: list[dict], shard_id: int) -> list[dict]:
    """Filter events that belong to a specific shard."""
    return [e for e in events if e.get('shard') == shard_id]


